1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface ScenarioOutput {
41	  results: unknown[];
42	}
43	
44	const PROCESSING_FEE = 5;
45	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number | undefined> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const basePremiumOfType = (type: string): number => {
60	  const basePremium = BASE_PREMIUMS[type];
61	  if (basePremium === undefined) {
62	    throw new Error(`unknown item type: ${type}`);
63	  }
64	  return basePremium;
65	};
66	
67	const CURSE_SURCHARGE_RATE = 0.5;
68	const HIGH_ENCHANTMENT_LEVEL = 5;
69	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
70	
71	const isCursed = (item: Item): boolean => item.cursed === true;
72	const isHighlyEnchanted = (item: Item): boolean =>
73	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
74	
75	/** Item-specific modifiers apply to the base premium of the affected item only. */
76	const itemSurchargesOf = (item: Item): number => {
77	  const basePremium = basePremiumOfType(item.type);
78	  const curseSurcharge = isCursed(item) ? basePremium * CURSE_SURCHARGE_RATE : 0;
79	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
80	    ? basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
81	    : 0;
82	  return curseSurcharge + highEnchantmentSurcharge;
83	};
84	
85	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
86	const COMPONENT_BLOCK_SIZE = 3;
87	const COMPONENT_BLOCK_PREMIUM = 60;
88	
89	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
90	
91	const countByType = (items: Item[]): Map<string, number> => {
92	  const counts = new Map<string, number>();
93	  for (const item of items) {
94	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
95	  }
96	  return counts;
97	};
98	
99	/**
100	 * Items of one type are normally priced individually. The exception is
101	 * components: exactly 3 alike ones form a "building block" priced as a unit.
102	 */
103	const typeGroupPremium = (type: string, count: number): number =>
104	  isComponent(type) && count === COMPONENT_BLOCK_SIZE
105	    ? COMPONENT_BLOCK_PREMIUM
106	    : count * basePremiumOfType(type);
107	
108	const policyBasePremiumOf = (items: Item[]): number =>
109	  [...countByType(items)].reduce(
110	    (sum, [type, count]) => sum + typeGroupPremium(type, count),
111	    0,
112	  );
113	
114	const isLongStanding = (customer: Customer): boolean =>
115	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
116	
117	/** What the policy-wide modifiers are judged against, beyond the items themselves. */
118	interface QuoteContext {
119	  customer: Customer;
120	  isFollowUpContract: boolean;
121	}
122	
123	/**
124	 * Policy-wide modifiers are signed rates charged against the policy base
125	 * premium: surcharges positive, discounts negative.
126	 */
127	const policyModifierRateFor = (context: QuoteContext): number =>
128	  INITIAL_ASSESSMENT_SURCHARGE_RATE -
129	  (isLongStanding(context.customer) ? LOYALTY_DISCOUNT_RATE : 0) -
130	  (context.isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
131	
132	const itemSurchargesOfPolicy = (items: Item[]): number =>
133	  items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
134	
135	/** Kept as an exact fraction — only the final premium is rounded. */
136	const premiumBeforeRounding = (items: Item[], context: QuoteContext): number => {
137	  const policyBasePremium = policyBasePremiumOf(items);
138	  const policyModifiers = policyBasePremium * policyModifierRateFor(context);
139	  return policyBasePremium + itemSurchargesOfPolicy(items) + policyModifiers + PROCESSING_FEE;
140	};
141	
142	/** Rounded up, in the MHPCO's favour. */
143	const finalPremiumFor = (items: Item[], context: QuoteContext): number =>
144	  Math.ceil(premiumBeforeRounding(items, context));
145	
146	const INSURANCE_VALUES: Record<string, number | undefined> = {
147	  sword: 1000,
148	  amulet: 600,
149	  staff: 800,
150	  potion: 400,
151	  rune: 250,
152	  moonstone: 250,
153	};
154	
155	const DEDUCTIBLE = 100;
156	const CAP_MULTIPLIER = 2;
157	
158	const insuranceSumOf = (items: Item[]): number =>
159	  items.reduce((sum, item) => sum + (INSURANCE_VALUES[item.type] ?? 0), 0);
160	
161	/** A policy created by a quote step, tracked so later claims can draw on it. */
162	interface Policy {
163	  items: Item[];
164	  remainingCap: number;
165	}
166	
167	/** The most a policy will ever pay out, across all claims against it. */
168	const capFor = (items: Item[]): number => insuranceSumOf(items) * CAP_MULTIPLIER;
169	
170	const openPolicyFor = (items: Item[]): Policy => ({ items, remainingCap: capFor(items) });
171	
172	const CLAIM_HIGH_ENCHANTMENT_LEVEL = 8;
173	const CLAIM_HIGH_ENCHANTMENT_RATE = 0.5;
174	
175	/**
176	 * Unrelated to the high-enchantment premium surcharge: that one is judged
177	 * against HIGH_ENCHANTMENT_LEVEL, this one against its own, higher threshold.
178	 */
179	const qualifiesForHalfReimbursement = (insuredItem: Item): boolean =>
180	  (insuredItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_LEVEL;
181	
182	/** The share of the damage the MHPCO reimburses, before the deductible. */
183	const reimbursementRateFor = (insuredItem: Item): number =>
184	  qualifiesForHalfReimbursement(insuredItem) ? CLAIM_HIGH_ENCHANTMENT_RATE : 1;
185	
186	const payoutForDamage = (damage: Damage, insuredItem: Item): number =>
187	  damage.amount * reimbursementRateFor(insuredItem) - DEDUCTIBLE;
188	
189	const insuredItemFor = (damage: Damage, policy: Policy): Item => {
190	  const insuredItem = policy.items.find((item) => item.type === damage.itemType);
191	  if (insuredItem === undefined) {
192	    throw new Error(`claim references uninsured item type ${damage.itemType}`);
193	  }
194	  return insuredItem;
195	};
196	
197	interface Settlement {
198	  payout: number;
199	  remainingCap: number;
200	}
201	
202	/**
203	 * Draws against the policy's remaining cap, which it depletes.
204	 * Rounded down, in the MHPCO's favour.
205	 */
206	const settleClaim = (step: ClaimStep, policy: Policy): Settlement => {
207	  const claimed = step.incident.damages.reduce(
208	    (sum, damage) => sum + payoutForDamage(damage, insuredItemFor(damage, policy)),
209	    0,
210	  );
211	  const payout = Math.floor(Math.min(claimed, policy.remainingCap));
212	
213	  policy.remainingCap -= payout;
214	  return { payout, remainingCap: policy.remainingCap };
215	};
216	
217	const policyReferencedBy = (step: ClaimStep, policies: Map<number, Policy>): Policy => {
218	  const policy = policies.get(step.policy);
219	  if (policy === undefined) {
220	    throw new Error(`claim references unknown policy at step ${String(step.policy)}`);
221	  }
222	  return policy;
223	};
224	
225	export const runScenario = (scenario: Scenario): ScenarioOutput => {
226	  const policies = new Map<number, Policy>();
227	
228	  const results = scenario.steps.map((step, stepIndex) => {
229	    if (step.op === "claim") {
230	      return settleClaim(step, policyReferencedBy(step, policies));
231	    }
232	
233	    // Every quote but the first is a follow-up contract for this customer.
234	    const isFollowUpContract = policies.size > 0;
235	    policies.set(stepIndex, openPolicyFor(step.items));
236	
237	    return {
238	      premium: finalPremiumFor(step.items, { customer: scenario.customer, isFollowUpContract }),
239	    };
240	  });
241	
242	  return { results };
243	};
